// ======================================
// 1. LIGHT / DARK / AUTO THEME
// ======================================

const themeButtons = document.querySelectorAll("[data-theme-choice]");

function getAutomaticTheme() {
  const hour = new Date().getHours();
  return hour >= 6 && hour < 18 ? "light" : "dark";
}

function applyTheme(preference) {
  const selectedTheme = preference === "auto" ? getAutomaticTheme() : preference;
  document.documentElement.setAttribute("data-theme", selectedTheme);

  themeButtons.forEach((button) => {
    const active = button.dataset.themeChoice === preference;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  });

  const themeColor = document.querySelector('meta[name="theme-color"]');
  if (themeColor) {
    themeColor.setAttribute("content", selectedTheme === "dark" ? "#0b1120" : "#ffffff");
  }
}

function setThemePreference(preference) {
  localStorage.setItem("portfolio-theme", preference);
  applyTheme(preference);
}

const savedTheme = localStorage.getItem("portfolio-theme") || "auto";
applyTheme(savedTheme);

themeButtons.forEach((button) => {
  button.addEventListener("click", () => {
    setThemePreference(button.dataset.themeChoice);
  });
});

setInterval(() => {
  if ((localStorage.getItem("portfolio-theme") || "auto") === "auto") {
    applyTheme("auto");
  }
}, 60000);

document.addEventListener("visibilitychange", () => {
  if (!document.hidden && (localStorage.getItem("portfolio-theme") || "auto") === "auto") {
    applyTheme("auto");
  }
});


